styles.css:
/* chat-desk P2 骨架样式：token 全取宿主 --c-* 变量，禁硬编码色值（check 与 build 同步自检） */
.cd-root{display:flex;flex-direction:column;height:100%;min-height:0;min-width:0;overflow:hidden;background:rgb(var(--c-bg-base));color:rgb(var(--c-text-primary));font-family:var(--font-sans,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif);font-size:14px}
.cd-toolbar{flex:none;display:flex;align-items:center;gap:8px;padding:6px 10px;border-bottom:1px solid rgb(var(--c-border)/0.1);background:rgb(var(--c-bg-elevated))}
.cd-title{font-size:12px;font-weight:600;color:rgb(var(--c-text-secondary));min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}
.cd-badge{flex:none;font-size:10px;padding:1px 6px;border-radius:999px;background:rgb(var(--c-primary)/0.14);color:rgb(var(--c-primary))}
.cd-badge-off{background:rgb(var(--c-bg-hover));color:rgb(var(--c-text-muted))}
.cd-msgs{flex:1;min-height:0;overflow-y:auto;scrollbar-width:thin}
.cd-msg{padding:8px 14px}
.cd-role{font-size:10px;font-weight:700;letter-spacing:.04em;margin-bottom:3px;color:rgb(var(--c-text-tertiary))}
.cd-role-user{color:rgb(var(--c-primary))}
.cd-role-ai{color:rgb(var(--c-status-success))}
.cd-bubble{font-size:13px;line-height:1.6;white-space:pre-wrap;word-break:break-word;color:rgb(var(--c-text-primary))}
.cd-msg-user .cd-bubble{background:rgb(var(--c-primary)/0.1);border:1px solid rgb(var(--c-primary)/0.18);border-radius:9px;padding:7px 10px;display:inline-block}
.cd-tool{display:flex;align-items:center;gap:6px;margin-top:4px;padding:4px 8px;border-radius:6px;background:rgb(var(--c-bg-hover)/0.6);font-size:11px;color:rgb(var(--c-text-secondary))}
.cd-tool-name{font-weight:600}
.cd-tool-status-ok{color:rgb(var(--c-status-success))}
.cd-tool-status-err{color:rgb(var(--c-status-danger))}
.cd-think{margin:2px 0 4px;padding:5px 8px;border-left:2px solid rgb(var(--c-border)/0.3);font-size:11px;line-height:1.55;color:rgb(var(--c-text-tertiary));white-space:pre-wrap;word-break:break-word}
.cd-caret{display:inline-block;width:2px;height:1.05em;margin-left:2px;vertical-align:-0.15em;background:currentColor;opacity:.8;animation:cd-blink 1s steps(1,end) infinite}
@keyframes cd-blink{0%,49%{opacity:1}50%,100%{opacity:0}}
.cd-inputrow{flex:none;display:flex;gap:6px;padding:8px 10px;border-top:1px solid rgb(var(--c-border)/0.1);background:rgb(var(--c-bg-elevated))}
.cd-input{flex:1;min-width:0;box-sizing:border-box;padding:7px 10px;border:1px solid rgb(var(--c-border)/0.14);border-radius:8px;background:rgb(var(--c-bg-surface));color:rgb(var(--c-text-primary));font-size:13px;font-family:inherit;outline:none;resize:none}
.cd-input:focus{border-color:rgb(var(--c-primary)/0.7)}
.cd-input::placeholder{color:rgb(var(--c-text-muted))}
.cd-btn{flex:none;padding:7px 12px;border:1px solid rgb(var(--c-border)/0.12);border-radius:8px;background:rgb(var(--c-bg-surface));color:rgb(var(--c-text-primary));font-size:12px;cursor:pointer;white-space:nowrap}
.cd-btn:hover:not(:disabled){background:rgb(var(--c-bg-hover))}
.cd-btn:disabled{opacity:.5;cursor:default}
.cd-btn-primary{background:rgb(var(--c-primary));border-color:rgb(var(--c-primary));color:rgb(var(--c-on-primary))}
.cd-btn-danger{background:rgb(var(--c-status-danger));border-color:rgb(var(--c-status-danger));color:rgb(var(--c-bg-base))}
.cd-sessions{flex:none;max-height:180px;overflow-y:auto;border-bottom:1px solid rgb(var(--c-border)/0.08);scrollbar-width:thin}
.cd-sessrow{display:flex;align-items:center;gap:8px;padding:6px 14px;cursor:pointer;border-bottom:1px solid rgb(var(--c-border)/0.05)}
.cd-sessrow:hover{background:rgb(var(--c-bg-hover)/0.55)}
.cd-sessrow-on{background:rgb(var(--c-primary)/0.1)}
.cd-sess-title{flex:1;min-width:0;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:rgb(var(--c-text-primary))}
.cd-sess-meta{flex:none;font-size:10px;color:rgb(var(--c-text-tertiary))}
.cd-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:40px 20px;color:rgb(var(--c-text-tertiary));font-size:12.5px;text-align:center}
.cd-err{margin:8px 14px;padding:8px 10px;border-radius:8px;border:1px solid rgb(var(--c-status-danger)/0.3);background:rgb(var(--c-status-danger)/0.08);color:rgb(var(--c-status-danger));font-size:12px}
